import { Component, h, Prop, Element, State } from '@stencil/core';
import { setCssVariableValueDeprecated } from '../../utils/utils';

@Component({
  tag: 'std-table',
  styleUrl: 'std-table.css',
  shadow: true
})
export class StdTableThComponent {
  @Prop() titleTh: string;

  @State() label: any;

  @Element() el: HTMLElement;

  componentDidLoad() {
    this.setVariant();
  }

  private setVariant() {
    let cssVars;
    cssVars = [{ key: 'display', value: 'flex' }];
    setCssVariableValueDeprecated(this.el, 'slot', cssVars);
  }

  render() {
    return (
      <div class="relative overflow-x-auto">
        <div class="flex items-center justify-end gap-6">
          <div>
            <i class="icon-chefron-left text-2xl leading-none"></i>
          </div>
          <ul class="flex items-center gap-2">
            <li class="text-base font-bold">1</li>
            <li>...</li>
            <li></li>
          </ul>
          <div>
            <i class="icon-chevron-right text-2xl leading-none"></i>
          </div>
        </div>
        <table class="w-full text-sm text-left">
          <thead class="bg-alternative-light h-16">
            <tr class="border-b border-alternative-medium">
              <slot name="tableTh" />
            </tr>
          </thead>
          <tbody>
            <slot name="tableBody" />
          </tbody>
        </table>
      </div>
    );
  }
}
